sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  // ----- Wizard steps -----
  c.steps = [
    { key: 'new',      label: 'New' },
    { key: 'details',  label: 'Hackathon Details' },
    { key: 'duration', label: 'Duration' },
    { key: 'rules',    label: 'Rules' }
  ];
  c.stepIndex = 0;

  // ----- Record picker field (sn-record-picker expects a 'field' object) -----
  c.userField = { name: 'user', value: '', displayValue: '' }; // value = sys_id

  // ----- Form model (use your custom table field names) -----
  c.form = {
    name: '',                       // display name (for UI/validation only)
    email: '',
    hackathon_name: '',
    hackathon_registration: '',
    start_date_time: '',
    end_date_time: '',
    rules: ''
  };

  // ----- UI state -----
  c.state = { submitting:false, done:false, error:'', record:null };
  c.dateError = false;

  // ----- sn-record-picker -> capture user sys_id + display and fetch email -----
  $scope.$on('field.change', function(evt, parms) {
    if (parms && parms.field && parms.field.name === 'user') {
      c.userField.value = parms.newValue || ''; // sys_id
      c.userField.displayValue = parms.displayValue || parms.field.displayValue || '';
      c.form.name = c.userField.displayValue || ''; // keep for UI/validation

      if (c.userField.value) {
        c.server.get({ action:'get_user_email', sys_id: c.userField.value })
          .then(function(resp){ c.form.email = (resp.data && resp.data.email) || ''; });
      } else {
        c.form.email = '';
      }
      $scope.$applyAsync();
    }
  });

  // ----- Navigation -----
  c.prev = function() {
    if (c.state.done || c.state.submitting) return;
    if (c.stepIndex > 0) c.stepIndex--;
  };

  c._validateCurrent = function() {
    if (c.stepIndex === 0) {
      if (!c.form.name)  return 'Name is required';
      if (!c.form.email) return 'Email is required (auto-fill failed)';
    }
    if (c.stepIndex === 1 && !c.form.hackathon_name) return 'Hackathon name is required';
    if (c.stepIndex === 2) {
      if (!c.form.start_date_time || !c.form.end_date_time) return 'Start and End date/time are required';
      try {
        var s = new Date(c.form.start_date_time), e = new Date(c.form.end_date_time);
        c.dateError = e < s; if (c.dateError) return 'End must be after Start';
      } catch(e){}
    }
    return '';
  };
  c.canNext   = function(){ return !c._validateCurrent(); };
  c.canSubmit = function(){ return !c._validateCurrent(); };

  c.next = function(){
    if (c.state.done || c.state.submitting) return;
    var err = c._validateCurrent(); c.state.error = err || '';
    if (!err && c.stepIndex < c.steps.length - 1) c.stepIndex++;
  };

  // ----- Submit → create record in x_1097288_hacktaho_hackathon_registration -----
  c.submit = function(){
    if (c.state.done || c.state.submitting) return;
    var err = c._validateCurrent(); c.state.error = err || ''; if (err) return;

    c.state.submitting = true;

    // IMPORTANT: include user sys_id for the 'name' reference
    var payload = angular.extend({}, c.form, {
      user_sys_id: c.userField.value,          // <-- reference value
      user_display: c.userField.displayValue   // optional, for logging
    });

    c.server.get({ action: 'create_registration', payload: payload })
      .then(function(resp){
        if (resp.data && resp.data.error) { c.state.error = resp.data.error; return; }
        c.state.record = resp.data && resp.data.record ? resp.data.record : null;
        if (c.state.record) c.state.done = true; // freeze buttons
      })
      .catch(function(){
        c.state.error = 'Failed to create registration';
      })
      .finally(function(){
        c.state.submitting = false;
      });
  };
};

sp_widget.css:
.hw-card { background: #fff; padding: 20px; border-radius: 8px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }
.hw-title { margin-top: 0; margin-bottom: 16px; }
.hw-steps { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.hw-step { padding: 8px 12px; border-radius: 16px; background: #e9ecef; font-weight: 600; }
.hw-step.active { background: #13854e; color: #fff; }
.hw-step.done { background: #58a67a; color: #fff; }
.hw-panel { margin-top: 8px; }
.m-t-16 { margin-top: 16px; }
.m-t-8 { margin-top: 8px; }
.hw-footer { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }

sp_widget.script:
(function() {
  data.error = '';
  if (!input) return;

  // Normalize HTML5 datetime-local ('YYYY-MM-DDTHH:mm') to instance display format
  function toDisplay(v) {
    if (!v) return '';
    var s = ('' + v).replace('T', ' ');
    if (s.length === 16) s += ':00'; // add seconds if missing
    return s;
  }

  try {
    // --- Email lookup for selected user (sys_id) ---
    if (input.action === 'get_user_email') {
      var u = new GlideRecord('sys_user');
      data.email = (u.get(String(input.sys_id)) ? String(u.getValue('email')) : '');
      return;
    }

    // --- Create registration in custom table ---
    if (input.action === 'create_registration') {
      var p = input.payload || {};

      // Server-side validation
      if (!p.user_sys_id && !p.name) throw 'Name is required';
      if (!p.email) throw 'Email is required';
      if (!p.hackathon_name) throw 'Hackathon name is required';
      if (!p.start_date_time || !p.end_date_time) throw 'Start and End date/time are required';

      var sdt = new GlideDateTime(); sdt.setDisplayValue(toDisplay(p.start_date_time));
      var edt = new GlideDateTime(); edt.setDisplayValue(toDisplay(p.end_date_time));
      if (edt.getNumericValue() < sdt.getNumericValue())
        throw 'End date/time must be after Start date/time';

      var gr = new GlideRecord('x_1097288_hacktaho_hackathon_registration');
      gr.initialize();

      // 'name' is a reference to sys_user in your table; set sys_id, not label
      var nameIsRef = false;
      try { nameIsRef = gr.getElement('name').getED().getInternalType() === 'reference'; } catch(e) {}

      var userSysId = String(p.user_sys_id || '');

      // Safety fallback: if no sys_id but we have a display name, try lookup by name
      if (!userSysId && p.name) {
        var u = new GlideRecord('sys_user');
        u.addQuery('name', p.name);
        u.setLimit(1);
        u.query();
        if (u.next()) userSysId = '' + u.getUniqueValue();
      }

      if (nameIsRef) {
        if (!userSysId) throw 'User (sys_id) is required for reference field "name"';
        gr.setValue('name', userSysId);              // correct: reference expects sys_id
      } else {
        gr.setValue('name', p.name || p.user_display || '');
      }

      // Straight mappings
      gr.setValue('email',                   p.email);
      gr.setValue('hackathon_name',          p.hackathon_name);
      gr.setValue('hackathon_registration',  p.hackathon_registration || '');
      gr.setValue('start_date_time',         sdt);
      gr.setValue('end_date_time',           edt);
      gr.setValue('rules',                   p.rules || '');

      var id = gr.insert();

      // Return something nice to show in the banner
      var display =
        (gr.isValidField('number') && gr.getValue('number')) ? String(gr.getValue('number')) :
        (gr.getDisplayValue() || String(id));

      data.record = { sys_id: String(id), display: display };
      return;
    }

    data.error = 'Unsupported action';

  } catch (e) {
    data.error = String(e);
  }
})();
